// Schreibt jeden Montag den „Wochenstand“ der Vorwoche als Notiz (Aufgaben, Vorschläge, Fälligkeiten).
// Ist die Einstellung „firmenwissen_projekt“ gesetzt, liegt die Notiz in diesem Projekt und beim ersten Lauf werden Projekt und zwei neutrale Startnotizen angelegt.
// Ohne diese Einstellung wird nichts angelegt außer der Wochenstand-Notiz selbst (ohne Projekt).
// Keine Arbeitszeiten, keine Kontaktdaten, keine Zugangsdaten.
const D = $('Team-Daten laden').first().json || {};
// --- Einstellungen dieses Kunden (Tabelle team_einstellungen, Knoten „Einstellungen laden“) ---
const EINST = {};
try { for (const r of $('Einstellungen laden').all().map(i => i.json)) { if (r && typeof r.schluessel === 'string' && r.wert !== undefined) EINST[r.schluessel] = r.wert; } } catch (e) { /* Knoten hat nichts geliefert: es gelten die Standardwerte */ }
if (D.einstellungen && typeof D.einstellungen === 'object') { if (Array.isArray(D.einstellungen)) { for (const r of D.einstellungen) { if (r && typeof r.schluessel === 'string' && r.wert !== undefined) EINST[r.schluessel] = r.wert; } } else Object.assign(EINST, D.einstellungen); }
const einst = (k, std) => (EINST[k] === undefined || EINST[k] === null || EINST[k] === '' ? std : EINST[k]);
const STICHTAG = /^\d{4}-\d{2}-\d{2}$/.test(String(einst('stichdatum_abrechnung', ''))) ? String(einst('stichdatum_abrechnung')) : new Date().getFullYear() + '-01-01';
// Module: im Pilot ist nur Planer/Übersicht an. Einschalten über die Einstellung „module“, z. B. {"zeit": true}
const MODULE = { zeit: false, social: false, system: false, kurs: false };
{ const mo = einst('module', null); if (mo && typeof mo === 'object' && !Array.isArray(mo)) for (const k of Object.keys(MODULE)) MODULE[k] = mo[k] === true; }
const alle = (D.mitglieder || []).filter(m => m && m.mitglied_id);
// Autor der Notizen: erstes Mitglied mit Rolle admin (kein Name im Workflow festverdrahtet)
const admin = alle.find(m => m.rolle === 'admin' && m.status !== 'gesperrt');
if (!admin) throw new Error('Im Team gibt es keinen Admin. Der Wochenstand wurde nicht geschrieben.');
const name = id => (alle.find(m => m.mitglied_id === id) || {}).name || id || '–';
const tz = d => new Date(d).toLocaleDateString('sv-SE', { timeZone: 'Europe/Berlin' });
const heute = tz(Date.now());
const tagDate = s => new Date(s + 'T12:00:00Z');
const plus = (s, n) => { const d = tagDate(s); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const wd = (tagDate(heute).getUTCDay() + 6) % 7; // 0 = Montag
const montagDiese = plus(heute, -wd);
// Montags: komplette Vorwoche. An anderen Tagen (z. B. manueller Lauf): Zwischenstand der laufenden Woche – wird am Montag überschrieben.
const zwischen = wd !== 0;
const von = zwischen ? montagDiese : plus(montagDiese, -7), bis = zwischen ? heute : plus(montagDiese, -1);
const isoWoche = ds => { const t = tagDate(ds); const w0 = (t.getUTCDay() + 6) % 7; t.setUTCDate(t.getUTCDate() - w0 + 3); const j = t.getUTCFullYear(); const e = new Date(Date.UTC(j, 0, 4)); const w = 1 + Math.round(((t - e) / 864e5 - 3 + ((e.getUTCDay() + 6) % 7)) / 7); return { j, w }; };
const kw = isoWoche(von);
const inWoche = ts => { if (!ts) return false; const d = tz(ts); return d >= von && d <= bis; };
const fmt = s => s ? s.slice(8, 10) + '.' + s.slice(5, 7) + '.' : '';

const A = (D.aufgaben || []).filter(a => a && a.aufgabe_id);
const erledigt = A.filter(a => a.status === 'Erledigt' && inWoche(a.erledigt_am));
const neu = A.filter(a => inWoche(a.erstellt));
const offen = A.filter(a => a.status !== 'Erledigt');
const naechste = offen.filter(a => a.deadline && a.deadline >= heute && a.deadline <= plus(heute, 6)).sort((a, b) => a.deadline.localeCompare(b.deadline));
const ueberfaellig = offen.filter(a => a.deadline && a.deadline < heute);
const V = (D.vorschlaege || []);
const vNeu = V.filter(v => inWoche(v.erstellt));
const vUm = V.filter(v => v.status === 'umgesetzt' && inWoche(v.geaendert));

const liste = (arr, f, leer) => arr.length ? arr.map(x => '- ' + f(x)).join('\n') : '- ' + leer;
const text = [
  (zwischen ? 'Zwischenstand der laufenden Woche, wird am Montag durch den vollständigen Wochenstand ersetzt. ' : '') + 'Automatisch erstellt am ' + fmt(heute) + heute.slice(0, 4) + ' aus dem Team-Portal. Zeitraum: ' + fmt(von) + ' bis ' + fmt(bis) + bis.slice(0, 4) + '.',
  '', '## Erledigt (' + erledigt.length + ')',
  liste(erledigt, a => a.titel + ' – ' + name(a.verantwortlich) + (a.projekt ? ' (' + a.projekt + ')' : ''), 'nichts als erledigt markiert'),
  '', '## Neu angelegt (' + neu.length + ')',
  liste(neu.slice(0, 40), a => a.titel + ' – zuständig ' + name(a.verantwortlich) + ', Prio ' + a.prio + (a.deadline ? ', bis ' + fmt(a.deadline) : ''), 'keine neuen Aufgaben'),
  '', '## Vorschläge zum Portal',
  liste(vNeu.map(v => 'neu: ' + v.titel + ' (von ' + name(v.autor) + ')').concat(vUm.map(v => 'umgesetzt: ' + v.titel)), x => x, 'keine Änderungen'),
  '', '## Fällig in den nächsten 7 Tagen (' + naechste.length + ')',
  liste(naechste, a => fmt(a.deadline) + ' ' + a.titel + ' – ' + name(a.verantwortlich), 'keine Deadlines'),
  '', '## Überfällig (' + ueberfaellig.length + ')',
  liste(ueberfaellig.slice(0, 20), a => a.titel + ' – ' + name(a.verantwortlich) + ', war fällig ' + fmt(a.deadline), 'nichts überfällig'),
  '', 'Stand der offenen Aufgaben insgesamt: ' + offen.length + '.'
].join('\n');

const jetzt = new Date().toISOString();
const ops = [];
// Projekt für Firmenwissen: nur wenn die Einstellung „firmenwissen_projekt“ gesetzt ist (true = Name „Firmenwissen“, oder ein eigener Name als Text)
const fw = einst('firmenwissen_projekt', null);
const fwName = typeof fw === 'string' && fw.trim() ? fw.trim().slice(0, 60) : (fw === true ? 'Firmenwissen' : '');
const wer = String(einst('kurzname', '') || einst('firma', '') || 'unserem Team');
if (fwName) {
  const projId = 'j_' + (fwName.toLowerCase().replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss').replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 30) || 'wissen');
  const proj = (D.projekte || []).find(p => p && String(p.name).toLowerCase() === fwName.toLowerCase());
  if (!proj) ops.push({ methode: 'POST', pfad: 'team_projekte', body: { projekt_id: projId, name: fwName, beschreibung: 'Wissen für das Team. Neueste Infos in „Aktuelles“ eintragen, immer mit Datum.', status: 'aktiv', farbe: '#1FA9B0', verantwortlich: admin.mitglied_id, reihenfolge: 90, geaendert: jetzt } });
  const hatNotiz = t => (D.notizen || []).some(n => n && String(n.titel).toLowerCase() === t.toLowerCase());
  if (!hatNotiz('Aktuelles')) ops.push({ methode: 'POST', pfad: 'team_notizen', body: { notiz_id: 'n_aktuelles', titel: 'Aktuelles', projekt: fwName, autor: admin.mitglied_id, geaendert_von: admin.mitglied_id, erstellt: jetzt, geaendert: jetzt, inhalt:
    'Neuigkeiten bei ' + wer + ' – neueste oben, immer mit Datum. Keine Passwörter hier eintragen.\n\n## TT.MM.JJJJ\n- Hier die erste Neuigkeit eintragen.' } });
  if (!hatNotiz('Über uns')) ops.push({ methode: 'POST', pfad: 'team_notizen', body: { notiz_id: 'n_ueber_uns', titel: 'Über uns', projekt: fwName, autor: admin.mitglied_id, geaendert_von: admin.mitglied_id, erstellt: jetzt, geaendert: jetzt, inhalt:
    'Grundlagen zu ' + wer + '. Bitte aktuell halten.\n\n## Wer wir sind\n- (kurz eintragen)\n\n## Was wir anbieten\n- (kurz eintragen)\n\n## Wichtige Werkzeuge\n- (kurz eintragen)' } });
}
const id = 'n_wochenstand_' + kw.j + 'w' + String(kw.w).padStart(2, '0');
ops.push({ methode: 'POST', pfad: 'team_notizen?on_conflict=notiz_id', upsert: true, body: { notiz_id: id, titel: 'Wochenstand KW ' + String(kw.w).padStart(2, '0') + '/' + kw.j, projekt: fwName, inhalt: text, autor: admin.mitglied_id, geaendert_von: admin.mitglied_id, erstellt: jetzt, geaendert: jetzt } });
return ops.map(o => ({ json: o }));
